'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "encoding": {
    "y": {
      "field": "Driver",
      "type": "nominal",
      "sort": [
        "NETWORK",
        "LOW COMPLEXITY",
        "NO PRIVILEGES",
        "NO USER ACTION"
      ],
      "axis": {
        "title": null,
        "domain": false,
        "ticks": false,
        "labelColor": "#F8FAFC",
        "labelFont": "Segoe UI",
        "labelFontSize": 11,
        "labelFontWeight": "bold",
        "labelPadding": 10,
        "labelLimit": 145
      }
    },
    "tooltip": [
      {
        "field": "Driver",
        "type": "nominal",
        "title": "Risk Driver"
      },
      {
        "field": "Risk Driver KEVs",
        "type": "quantitative",
