      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "dx": -8,
        "font": "Segoe UI",
        "fontSize": 11,
        "fontWeight": "bold",
        "color": "#F8FAFC"
      },
      "encoding": {
        "x": {
          "field": "Risk Driver KEVs",
          "type": "quantitative"
        },
        "text": {
          "field": "Risk Driver KEVs",
          "type": "quantitative",
